seedFiles.app/billing.py:
"""Billing math."""


def calc_tot(items: list[dict]) -> float:
    return round(sum(i["price"] * i["qty"] for i in items), 2)

seedFiles.app/orders.py:
from app.billing import calc_tot


def order_summary(items: list[dict]) -> str:
    return f"Order total: {calc_tot(items):.2f}"

seedFiles.app/report.py:
from app.billing import calc_tot


def report_line(label: str, items: list[dict]) -> str:
    return f"{label}: {calc_tot(items):.2f}"

seedFiles.test_billing.py:
from app.billing import calculate_total
from app.orders import order_summary
from app.report import report_line

ITEMS = [{"price": 2.5, "qty": 2}, {"price": 1.0, "qty": 3}]


def test_total():
    assert calculate_total(ITEMS) == 8.0


def test_order_summary():
    assert order_summary(ITEMS) == "Order total: 8.00"


def test_report_line():
    assert report_line("Q1", ITEMS) == "Q1: 8.00"


def test_old_name_gone():
    import app.billing

    assert not hasattr(app.billing, "calc_tot")
